SELECT deliveries.id, deliveries.event_id, deliveries.destination_id, deliveries.status, deliveries.attempt_count, deliveries.next_attempt_at, deliveries.last_error, deliveries.delivered_at, deliveries.created_at, deliveries.updated_at, alert_events.id AS id_1, alert_events.event_key, alert_events.kind, alert_events.incident_id, alert_events.monitor_id, alert_events.payload, alert_events.created_at AS created_at_1, alert_destinations.id AS id_2, alert_destinations.name, alert_destinations.url, alert_destinations.enabled, alert_destinations.created_at AS created_at_2, alert_destinations.updated_at AS updated_at_1 
FROM deliveries JOIN alert_events ON alert_events.id = deliveries.event_id JOIN alert_destinations ON alert_destinations.id = deliveries.destination_id 
WHERE deliveries.status IN (%(status_1_1)s::VARCHAR, %(status_1_2)s::VARCHAR) AND deliveries.next_attempt_at <= %(next_attempt_at_1)s::TIMESTAMP WITH TIME ZONE ORDER BY deliveries.next_attempt_at, deliveries.id 
 LIMIT %(param_1)s::INTEGER FOR UPDATE OF deliveries SKIP LOCKED
